#!/bin/bash
# Uninstall script for Quba-Viewer
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Quba-Viewer..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Quba-Viewer if running..."
pkill -f "Quba-Viewer" 2>/dev/null || true

# Remove /Applications/Quba.app
echo "Removing /Applications/Quba.app..."
if [ -d "/Applications/Quba.app" ]; then
    rm -rf "/Applications/Quba.app" 2>/dev/null || true
elif [ -f "/Applications/Quba.app" ]; then
    rm -f "/Applications/Quba.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Quba
