fi

# Remove $HOME/Library/Preferences/org.quba-viewer.quba.2.plist
echo "Removing $HOME/Library/Preferences/org.quba-viewer.quba.2.plist..."
if [ -d "$HOME/Library/Preferences/org.quba-viewer.quba.2.plist" ]; then
