fi

# Remove $HOME/Library/Saved Application State/org.quba-viewer.viewer.savedState
echo "Removing $HOME/Library/Saved Application State/org.quba-viewer.viewer.savedState..."
if [ -d "$HOME/Library/Saved Application State/org.quba-viewer.viewer.savedState" ]; then
